// generar_280_voz_de_chiqui.js
// CHIQUI Entre Señales — La voz de Chiqui en el Resumen de Análisis
//
// El resumen del período ("Resumen inteligente") pasa a hablar con la
// VOZ del personaje. Chiqui es quien aprendió a observar, y ahora
// cuenta en primera persona lo que notó, en una tarjeta llamada:
//
//   🧠 Lo que Chiqui aprendió este mes
//
// La tarjeta tiene tres partes:
//   1) APERTURA en primera persona, con el tono del mes:
//      · estable  → "¡Estuve cuidando a [mascota] contigo este mes!"
//      · 🟡        → "Estuve atento a [mascota] y quiero contarte..."
//      · 🟠/🔴     → "Estuve observando de cerca a [mascota] este mes."
//   2) SÍNTESIS de datos observados (los hechos del período; es la
//      misma síntesis que ya se calculaba, con los números reales).
//   3) CIERRE con una conclusión cuyo TONO se adapta al estado, en
//      una caja con el color del semáforo:
//      · 🔴 deriva con claridad al veterinario
//      · 🟠 sugiere seguir de cerca y comentar en el control
//      · 🟡 invita a observar un poco más, sin alarmar
//      · 🟢 reconoce la constancia; y si además bajaron los paseos
//        respecto al mes anterior, un empujón amable a recuperarlos;
//        si subieron, lo celebra.
//
// CLAVE DE DISEÑO: la calidez se adapta a la gravedad. Chiqui NUNCA
// suena tierno o celebratorio cuando hay señales serias (eso destruiría
// la confianza), ni regaña cuando baja la actividad. Cariñoso cuando
// todo va bien, sereno y directo cuando hay que mirar al veterinario.
//
// No es un motor nuevo de conclusiones: es una capa de personaje sobre
// el mismo estado y la misma síntesis que ya se calculaban. No inventa
// juicios de salud nuevos.
//
// No hay SQL. Solo reescribe app/analisis/page.tsx.
//
// Uso:
//   node generar_280_voz_de_chiqui.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/analisis/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
